param()
$ErrorActionPreference='Stop';$root=$PSScriptRoot;$input=Join-Path $root 'input';$out=Join-Path $root 'outputs';New-Item -ItemType Directory -Force -Path $out|Out-Null
try{$rows=@(Import-Csv (Join-Path $input 'records.csv'));$valid=@();$invalid=@();foreach($r in $rows){$reasons=@();if([string]::IsNullOrWhiteSpace($r.EmployeeId)){$reasons+='Missing EmployeeId'}if([string]::IsNullOrWhiteSpace($r.Email)-or $r.Email-notmatch '^[^@\s]+@[^@\s]+\.[^@\s]+$'){$reasons+='Invalid Email'}$age=0;if(-not [int]::TryParse($r.Age,[ref]$age)-or $age-lt 18-or $age-gt 65){$reasons+='Age must be 18-65'}if($reasons.Count-eq 0){$valid+=$r}else{$invalid+=[pscustomobject]@{EmployeeId=$r.EmployeeId;Name=$r.Name;Email=$r.Email;Age=$r.Age;ValidationErrors=($reasons-join '; ')}}};$valid|Export-Csv (Join-Path $out 'ValidRecords.csv') -NoTypeInformation;$invalid|Export-Csv (Join-Path $out 'InvalidRecords.csv') -NoTypeInformation;$summary="Records processed: $($rows.Count)`r`nValid records: $($valid.Count)`r`nInvalid records: $($invalid.Count)`r`nValidation rules: EmployeeId required; valid email required; age 18-65.";Set-Content (Join-Path $out 'Summary.txt') $summary -Encoding UTF8;if($rows.Count-ne 5-or $valid.Count-ne 3-or $invalid.Count-ne 2){throw 'Validation verification failed'};Write-Output "Validated $($rows.Count) records: $($valid.Count) valid, $($invalid.Count) invalid."}catch{$_|Out-String|Set-Content (Join-Path $out 'error.log');throw}
